$allUsers=rows('SELECT * FROM users ORDER BY role,full_name');$userCount=count($allUsers);$presentCount=count(array_filter($attendance,fn($a)=>in_array($a['status'],['Present','Late'],true)));$attendancePct=count($attendance)?round($presentCount/count($attendance)*100,1):0;$pendingFee=array_sum(array_map(fn($f)=>(float)$f['amount'],array_filter($fees,fn($f)=>$f['status']!=='Paid')));$openMessages=count(array_filter($messages,fn($m)=>$m['status']!=='Resolved'));$flashes=getFlash();
?>
