<script>
const gen=document.getElementById('generate-account-password');if(gen)gen.addEventListener('click',()=>{const chars='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#$%';let p='';for(let i=0;i<14;i++)p+=chars[crypto.getRandomValues(new Uint32Array(1))[0]%chars.length];document.getElementById('new_account_password').value=p;document.getElementById('new_account_password').type='text';});const toggle=document.getElementById('toggle-account-password');if(toggle)toggle.addEventListener('click',()=>{const p=document.getElementById('new_account_password');p.type=p.type==='password'?'text':'password';toggle.textContent=p.type==='password'?'Show':'Hide';});
</script></body></html>
