function table($heads,$rows){echo '<div class="table-wrap"><table><thead><tr>';foreach($heads as $h)echo '<th>'.e($h).'</th>';echo '</tr></thead><tbody>';if(!$rows){echo '<tr><td colspan="'.count($heads).'">No records to display.</td></tr>';}foreach($rows as $r){echo '<tr>';foreach($r as $v)echo '<td>'.e($v).'</td>';echo '</tr>';}echo '</tbody></table></div>';}
